// Vector Addition Kernel
void vector_add(const float* A, const float* B, float* C, int N) {
    #pragma loop_bound min(100) max(10000000)
    for (int i = 0; i < N; ++i) {
        C[i] = A[i] + B[i];
    }
}

gemv.source_code:
// Matrix-Vector Multiplication (GEMV)
void gemv_kernel(const float* A, const float* X, float* Y, int N, int M) {
    for (int i = 0; i < N; ++i) {
        float sum = 0.0f;
        for (int j = 0; j < M; ++j) {
            sum += A[i * M + j] * X[j];
        }
        Y[i] = sum;
    }
}

relu.source_code:
// Rectified Linear Unit (ReLU)
void relu_kernel(const float* X, float* Y, int N) {
    for (int i = 0; i < N; ++i) {
        Y[i] = (X[i] > 0.0f) ? X[i] : 0.0f;
    }
}

axpy.source_code:
// Fused AXPY Kernel (alpha * X[i] + Y[i])
void axpy(float alpha, const float* X, float* Y, int N) {
    #pragma loop_bound min(100) max(16777216)
    for (int i = 0; i < N; ++i) {
        Y[i] = alpha * X[i] + Y[i];
    }
}

reduction.source_code:
// Vector Sum Reduction Kernel
float vector_reduction(const float* A, int N) {
    float sum = 0.0f;
    for (int i = 0; i < N; ++i) {
        sum += A[i];
    }
    return sum;
}

elementwise_mul.source_code:
// Element-wise Vector Multiplication
void elementwise_mul(const float* A, const float* B, float* C, int N) {
    #pragma loop_bound min(100) max(16777216)
    for (int i = 0; i < N; ++i) {
        C[i] = A[i] * B[i];
    }
}
